-- Single-workspace deployment. Identity and all data remain on the company server.
CREATE TABLE schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE);
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, team_id uuid REFERENCES teams, manager_id uuid REFERENCES users, reviewer_id uuid REFERENCES users, permission_version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,kind text NOT NULL CHECK(kind IN ('JOB','ACCESS')),role text NOT NULL, scope text NOT NULL CHECK(scope IN ('SELF','TEAM','ALL')),team_id uuid REFERENCES teams,valid_from timestamptz NOT NULL DEFAULT now(),valid_to timestamptz,revoked_at timestamptz,granted_by uuid REFERENCES users,reason text NOT NULL, CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK(scope<>'TEAM' OR team_id IS NOT NULL));
CREATE INDEX grants_active ON grants(user_id,valid_from,valid_to) WHERE revoked_at IS NULL;
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,csrf text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings(key text PRIMARY KEY,value jsonb NOT NULL,version int NOT NULL DEFAULT 1,updated_by uuid REFERENCES users,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit(id bigserial PRIMARY KEY,actor_id uuid REFERENCES users,action text NOT NULL,object_type text NOT NULL,object_id text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,event_key text NOT NULL,message text NOT NULL,object_id uuid,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_key));
CREATE TABLE outbox(id bigserial PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,event_key text NOT NULL,message text NOT NULL,object_id uuid,processed_at timestamptz,attempts int NOT NULL DEFAULT 0,last_error text,UNIQUE(user_id,event_key));
CREATE TABLE idempotency(user_id uuid NOT NULL REFERENCES users,key text NOT NULL,hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,key));
CREATE TABLE tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code bigint GENERATED ALWAYS AS IDENTITY UNIQUE,title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 255),description text NOT NULL DEFAULT '',owner_id uuid NOT NULL REFERENCES users,created_by uuid NOT NULL REFERENCES users,reviewer_id uuid REFERENCES users,role text NOT NULL,type text NOT NULL DEFAULT 'OTHER',template_version int NOT NULL DEFAULT 1,status text NOT NULL CHECK(status IN ('DRAFT','ASSIGNED','ACCEPTED','IN_PROGRESS','SUBMITTED','CHANGES_REQUESTED','DONE','DECLINED','CANCELLED')),priority text NOT NULL DEFAULT 'NORMAL' CHECK(priority IN ('NORMAL','URGENT')),source text NOT NULL,original_due_at timestamptz,due_at timestamptz,occurred_at timestamptz,payload jsonb NOT NULL DEFAULT '{}',next_step text NOT NULL DEFAULT '',blocker text NOT NULL DEFAULT '',result_text text NOT NULL DEFAULT '',started_at timestamptz,approved_submission_id uuid,completed_at timestamptz,timing text CHECK(timing IN ('ON_TIME','LATE')),version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(status='DRAFT' OR due_at IS NOT NULL));
CREATE INDEX tasks_owner ON tasks(owner_id,role,status,due_at);
CREATE INDEX tasks_review ON tasks(reviewer_id,status);
CREATE TABLE assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES tasks,owner_id uuid NOT NULL REFERENCES users,status text NOT NULL CHECK(status IN ('PENDING','ACCEPTED','DECLINED','TIMED_OUT','SUPERSEDED')),assigned_at timestamptz NOT NULL DEFAULT now(),response_due_at timestamptz NOT NULL,calendar_snapshot jsonb NOT NULL,note text NOT NULL DEFAULT '',responded_at timestamptz);
CREATE UNIQUE INDEX one_assignment ON assignments(task_id) WHERE status='PENDING';
CREATE TABLE owner_history(id bigserial PRIMARY KEY,task_id uuid NOT NULL REFERENCES tasks,owner_id uuid NOT NULL REFERENCES users,role text NOT NULL,from_at timestamptz NOT NULL DEFAULT now(),to_at timestamptz,reason text NOT NULL);
CREATE TABLE supporters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES tasks,user_id uuid NOT NULL REFERENCES users,role text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','ACCEPTED','DECLINED','REVOKED')),note text NOT NULL DEFAULT '',responded_at timestamptz,summary text NOT NULL DEFAULT '',next_step text NOT NULL DEFAULT '',blocker text NOT NULL DEFAULT '',contribution_state text NOT NULL DEFAULT 'NOT_STARTED' CHECK(contribution_state IN ('NOT_STARTED','IN_PROGRESS','REPORTED_DONE')),reported_done_at timestamptz,version int NOT NULL DEFAULT 1,UNIQUE(task_id,user_id));
CREATE INDEX supports_user ON supporters(user_id,status);
CREATE TABLE task_events(id bigserial PRIMARY KEY,task_id uuid NOT NULL REFERENCES tasks,actor_id uuid REFERENCES users,action text NOT NULL,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE checkpoints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES tasks,title text NOT NULL,position int NOT NULL,required boolean NOT NULL DEFAULT false,state text NOT NULL DEFAULT 'OPEN' CHECK(state IN ('OPEN','DONE')),evidence text NOT NULL DEFAULT '',version int NOT NULL DEFAULT 1,UNIQUE(task_id,position));
CREATE TABLE submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES tasks,revision int NOT NULL,result_text text NOT NULL,payload jsonb NOT NULL,links jsonb NOT NULL DEFAULT '[]',submitted_at timestamptz NOT NULL DEFAULT now(),due_at_at_submit timestamptz NOT NULL,UNIQUE(task_id,revision));
ALTER TABLE tasks ADD CONSTRAINT approved_submission_fk FOREIGN KEY(approved_submission_id) REFERENCES submissions;
CREATE TABLE reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submission_id uuid NOT NULL UNIQUE REFERENCES submissions,actor_id uuid NOT NULL REFERENCES users,decision text NOT NULL CHECK(decision IN ('APPROVE','CHANGES_REQUESTED')),feedback text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deadline_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES tasks,requested_by uuid NOT NULL REFERENCES users,new_due_at timestamptz NOT NULL,old_due_at timestamptz NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'PENDING',decided_by uuid REFERENCES users,decided_at timestamptz,version int NOT NULL DEFAULT 1);
CREATE TABLE assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid REFERENCES tasks,record_id uuid,uploaded_by uuid NOT NULL REFERENCES users,role text NOT NULL,filename text NOT NULL,storage_key text NOT NULL UNIQUE,size bigint NOT NULL CHECK(size>0),sha256 text NOT NULL,mime text NOT NULL,shared boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CHECK(task_id IS NOT NULL OR record_id IS NOT NULL));
CREATE TABLE report_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,period date NOT NULL,role text NOT NULL,narrative jsonb NOT NULL DEFAULT '{}',version int NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,period,role));
CREATE TABLE reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,period date NOT NULL,UNIQUE(user_id,period));
CREATE TABLE report_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL REFERENCES reports,revision int NOT NULL,snapshot jsonb NOT NULL,recipients uuid[] NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(report_id,revision));
CREATE TABLE plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,period date NOT NULL,role text NOT NULL,title text NOT NULL,task_id uuid REFERENCES tasks,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
-- Professional content records: bounded typed payloads, never financial ledger/metric EAV.
CREATE TABLE records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),module text NOT NULL,kind text NOT NULL,role text NOT NULL,owner_id uuid NOT NULL REFERENCES users,company text NOT NULL DEFAULT '',title text NOT NULL,status text NOT NULL DEFAULT 'DRAFT',payload jsonb NOT NULL DEFAULT '{}',version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX records_scope ON records(module,owner_id,role,kind);
CREATE TABLE record_links(parent_id uuid NOT NULL REFERENCES records,child_id uuid NOT NULL REFERENCES records,relation text NOT NULL,PRIMARY KEY(parent_id,child_id,relation),CHECK(parent_id<>child_id));
CREATE TABLE employee_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_by uuid NOT NULL REFERENCES users,user_id uuid REFERENCES users,candidate_id uuid REFERENCES records,name text NOT NULL,birthday date,recruiter_id uuid REFERENCES users,employment_state text NOT NULL DEFAULT 'CANDIDATE' CHECK(employment_state IN ('CANDIDATE','PROBATION','OFFICIAL','LEFT')),probation_start date,official_start date,contract_date date,sensitive_cipher text,version int NOT NULL DEFAULT 1);
CREATE TABLE employment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employee_id uuid NOT NULL REFERENCES employee_profiles,kind text NOT NULL,business_date date NOT NULL,actor_id uuid REFERENCES users,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(employee_id,kind,business_date));
CREATE TABLE metric_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users,role text NOT NULL,platform text NOT NULL,shop text NOT NULL,currency text NOT NULL,kind text NOT NULL,checksum text NOT NULL,filename text NOT NULL,raw jsonb NOT NULL,preview jsonb,preview_hash text,status text NOT NULL DEFAULT 'UPLOADED',version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(platform,shop,kind,checksum));
CREATE TABLE metrics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),platform text NOT NULL,shop text NOT NULL,kind text NOT NULL,subject text NOT NULL,metric text NOT NULL,business_date date NOT NULL,window_end date NOT NULL,grain text NOT NULL,aggregation text NOT NULL CHECK(aggregation IN ('SUM','PERIOD_UNIQUE','RATIO','CUMULATIVE')),currency text NOT NULL,value numeric(28,10),missing_reason text,batch_id uuid REFERENCES metric_batches,owner_id uuid NOT NULL REFERENCES users,role text NOT NULL,revision int NOT NULL,source text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(value IS NOT NULL OR missing_reason IS NOT NULL),UNIQUE(platform,shop,kind,subject,metric,business_date,window_end,grain,currency,revision));
CREATE TABLE claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users,platform text NOT NULL,shop text NOT NULL,order_id text NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>=0),currency text NOT NULL,stage text NOT NULL DEFAULT 'UNSPECIFIED' CHECK(stage IN ('UNSPECIFIED','CLAIMED','APPROVED','RECEIVED')),note text NOT NULL DEFAULT '',version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(platform,shop,order_id));
CREATE TABLE claim_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),claim_id uuid NOT NULL REFERENCES claims,sku text NOT NULL,quantity numeric NOT NULL CHECK(quantity>0),allocation numeric(18,2) CHECK(allocation>=0));
CREATE TABLE platform_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),label text NOT NULL,platform text NOT NULL,login text NOT NULL,company text NOT NULL,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES platform_accounts,user_id uuid NOT NULL REFERENCES users,role text NOT NULL,valid_to timestamptz,revoked_at timestamptz,UNIQUE(account_id,user_id,role));
CREATE TABLE credential_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES platform_accounts,ciphertext text NOT NULL,actor_id uuid NOT NULL REFERENCES users,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approval_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL,company text NOT NULL,max_amount numeric(18,2),currency text NOT NULL,approvers uuid[] NOT NULL,enabled boolean NOT NULL DEFAULT false,version int NOT NULL DEFAULT 1,CHECK(max_amount IS NULL OR max_amount>=0),UNIQUE(kind,company));
CREATE TABLE requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users,kind text NOT NULL,title text NOT NULL,company text NOT NULL,amount numeric(18,2) CHECK(amount>=0),currency text NOT NULL,needed_on date,task_id uuid REFERENCES tasks,payload jsonb NOT NULL DEFAULT '{}',state text NOT NULL DEFAULT 'DRAFT',step int NOT NULL DEFAULT 0,policy_snapshot jsonb,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE request_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES requests,version int NOT NULL,snapshot jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,version));
CREATE TABLE approval_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES requests,request_version int NOT NULL,step int NOT NULL,actor_id uuid NOT NULL REFERENCES users,decision text NOT NULL,note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,request_version,step));
CREATE TABLE recurring_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users,role text NOT NULL,title text NOT NULL,type text NOT NULL DEFAULT 'OTHER',iso_weekdays int[] NOT NULL,due_hour int NOT NULL CHECK(due_hour BETWEEN 0 AND 23),enabled boolean NOT NULL DEFAULT false,version int NOT NULL DEFAULT 1);
CREATE TABLE generations(rule_id uuid NOT NULL REFERENCES recurring_rules,day date NOT NULL,task_id uuid NOT NULL REFERENCES tasks,PRIMARY KEY(rule_id,day));
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable historical record'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['audit','task_events','submissions','reviews','report_revisions','credential_versions','employment_events','request_revisions','approval_decisions','metrics'] LOOP EXECUTE format('CREATE TRIGGER immutable_%I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION immutable_record()',t,t); END LOOP; END $$;
